def request_language(request):
    preferences = []
    for position, item in enumerate(request.headers.get('accept-language', '').split(',')):
        parts = item.strip().lower().split(';')
        code = parts[0].split('-')[0]
        try:
            quality = next((float(p.strip()[2:]) for p in parts[1:] if p.strip().startswith('q=')), 1.0)
        except ValueError:
            continue
        if code in {'zh', 'en'} and 0 < quality <= 1:
            preferences.append((quality, -position, code))
    return max(preferences)[2] if preferences else 'zh'

def translate(text, language):
    return TRANSLATIONS.get(text, text) if language == 'en' else text

def language_prompt(context):
    if context.get('language') == 'en':
        return "\nResponse language: English. Write all user-facing answers, report headings, explanations and clarification questions in English, including when source documents or tool results are Chinese. Translate supported facts faithfully; preserve source filenames, identifiers and original quotations. Do not invent facts or change tool-use rules."
    return "\n回复语言：简体中文。所有回答、报告标题和追问使用简体中文；忠实转述知识库与工具结果，保留来源文件名、标识符及原文引用。"
